import { useEffect, useState } from 'react';
import BookGrid from '../components/BookGrid';
import { getBooks } from '../api/backend';

function Books() {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('all');

  const [books, setBooks] = useState([]);
  const [status, setStatus] = useState('loading');
  const [error, setError] = useState(null);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let ignore = false;
    async function load() {
      setStatus('loading');
      try {
        const list = await getBooks();
        if (!ignore) {
          setBooks(list);
          setStatus('success');
        }
      } catch (err) {
        if (!ignore) {
          setError(err);
          setStatus('error');
        }
      }
    }
    load();
    return () => { ignore = true; };
  }, [reloadKey]);

  const categories = [...new Set(books.map(b => b.category).filter(Boolean))].sort();
  const q = query.trim().toLowerCase();
  const shown = books.filter(b =>
    (category === 'all' || b.category === category) &&
    (q === '' || b.title.toLowerCase().includes(q) || b.author.toLowerCase().includes(q))
  );

  const chipClass = (active) =>
    'rounded-full border px-3 py-1 text-sm transition ' +
    (active ? 'border-amber-500 bg-amber-500 text-white' : 'border-amber-200 bg-white text-slate-600 hover:bg-amber-50');

  return (
    <div className="mx-auto max-w-5xl px-4 py-10 md:px-6">
      <div className="mb-4 flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div>
          <h1 className="text-2xl font-semibold text-slate-900">หนังสือทั้งหมด</h1>
          <p className="text-sm text-slate-500">
            {status === 'success' && `พบ ${shown.length} จาก ${books.length} เล่ม`}
          </p>
        </div>
        <input value={query} onChange={e => setQuery(e.target.value)}
               placeholder="ค้นหาชื่อหนังสือหรือผู้แต่ง..."
               className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 focus:border-amber-400 focus:outline-none focus:ring-2 focus:ring-amber-100 md:w-72" />
      </div>

      {/* หมวดหมู่ */}
      <div className="mb-6 flex flex-wrap gap-2">
        <button onClick={() => setCategory('all')} className={chipClass(category === 'all')}>ทุกหมวด</button>
        {categories.map(c => (
          <button key={c} onClick={() => setCategory(c)} className={chipClass(category === c)}>{c}</button>
        ))}
      </div>

      <BookGrid books={shown} status={status} error={error}
                onRetry={() => setReloadKey(k => k + 1)} />
    </div>
  );
}

export default Books;
